// ---------- NOTIFICATION HELPER - নতুন, আগেরটা অটুট ----------
async function sendNotify(toUserId: string, actorName: string, type: string, videoId: string | null, message: string) {
  try {
    const n = { id: "nt-" + Date.now() + "-" + Math.random().toString(36).slice(2,6), user_id: toUserId, actor_name: actorName, type, video_id: videoId, message, is_read: false, created_at: Date.now() };
    const old = getLocal("shorttok_notifications_" + toUserId, []);
    setLocal("shorttok_notifications_" + toUserId, [n, ...old].slice(0, 100));
    try { await sb.from("notifications").insert({ user_id: toUserId, actor_name: actorName, type, video_id: videoId, message } as any); } catch {}
    // Browser notification - টুপ করে
    try { if (Notification && Notification.permission === "granted") new Notification("Short Tok 🔔", { body: message }); else if (Notification && Notification.permission !== "denied") Notification.requestPermission(); } catch {}
  } catch {}
}
async function notifyAllFollowers(actorId: string, actorName: string, videoId: string, caption: string) {
  try {
    const { data } = await sb.from("follows").select("follower_id").eq("following_id", actorId);
    const ids = (data || []).map((x: any) => x.follower_id);
    // Local followers - যারা ফলো করেছে
    const localF = getLocal("shorttok_followers_" + actorId, []);
    const all = [...new Set([...ids, ...localF])];
    for (const uid of all) { if (uid !== actorId) await sendNotify(uid, actorName, "video", videoId, `🎬 ${actorName} নতুন ভিডিও পোস্ট করেছে: ${caption.slice(0, 40)}`); }
    // সবাইকে লোকাল নোটিফিকেশনও দেখাতে - হোমে যারা আছে
    const allUsers = getLocal("shorttok_all_users", []);
    for (const u of allUsers) { if (u !== actorId) await sendNotify(u, actorName, "video", videoId, `🎬 ${actorName} নতুন ভিডিও পোস্ট করেছে`); }
  } catch {}
}

function useSafeAuth() {
  const [authUser, setAuthUser] = useState<any>(null);
  useEffect(() => { let alive = true; (async () => { try { const { data } = await sb.auth.getSession(); if (alive) setAuthUser(data?.session?.user || null); } catch { if (alive) setAuthUser(null); } })(); let sub: any = null; try { const r = sb.auth.onAuthStateChange((_e: any, s: any) => { if (alive) setAuthUser(s?.user || null); }); sub = r?.data; } catch {} return () => { alive = false; try { sub?.subscription?.unsubscribe(); } catch {} }; }, []);
  return { user: authUser };
}
async function signBatch(paths: string[]): Promise<Map<string, string>> {
  const map = new Map<string, string>();
  const storagePaths = paths.filter((p) => !p.startsWith("http"));
  paths.filter((p) => p.startsWith("http")).forEach((p) => map.set(p, p));
  if (storagePaths.length) { try { const { data } = await sb.storage.from("videos").createSignedUrls(storagePaths, 60 * 60 * 8); (data ?? []).forEach((d: any) => { if (d.path && d.signedUrl) map.set(d.path, d.signedUrl); }); } catch {} }
  return map;
}
function usePersistLogin() {
  const { user } = useSafeAuth();
  const [savedUser, setSavedUser] = useState<any>(() => getLocal("shorttok_persist_login", null));
  const [showLogin, setShowLogin] = useState(false);
  useEffect(() => { (async () => { try { const { data } = await sb.auth.getSession(); const u = data?.session?.user; if (u) { const info = { id: u.id, email: u.email, name: (u.user_metadata as any)?.full_name || u.email?.split("@")[0] || "User", avatar: (u.user_metadata as any)?.avatar_url || "", at: Date.now() }; setLocal("shorttok_persist_login", info); setLS("shorttok_username", info.name); setLS("shorttok_user_email", info.email || ""); try { window.localStorage.removeItem("shorttok_logged_out"); } catch {} setSavedUser(info); const au = getLocal("shorttok_all_users", []); if (!au.includes(u.id)) setLocal("shorttok_all_users", [...au, u.id]); } else { const saved = getLocal("shorttok_persist_login", null); const loggedOut = getLS("shorttok_logged_out"); if (saved && !loggedOut) setSavedUser(saved); } } catch {} })(); }, []);
  const loginWithGoogle = async () => { try { const { error } = await sb.auth.signInWithOAuth({ provider: "google", options: { redirectTo: window.location.origin + "/feed", queryParams: { prompt: "select_account" } } }); if (error) throw error; } catch { toast.error("Gmail লগইন হয়নি, আবার চেষ্টা করো"); } };
  const logout = async () => { if (!confirm("Log Out করতে চাও?")) return; try { await sb.auth.signOut(); } catch {} try { window.localStorage.setItem("shorttok_logged_out", "1"); window.localStorage.removeItem("shorttok_persist_login"); } catch {} setSavedUser(null); toast.success("Log Out হয়ে গেছে"); window.location.href = "/feed"; };
  const deleteAccount = async () => { if (!confirm("তুমি কি সত্যিই তোমার অ্যাকাউন্ট + সব ভিডিও + Status মুছে ফেলতে চাও? এটা ফেরানো যাবে না।")) return; if (!confirm("আবার কনফার্ম করো - অ্যাকাউন্ট ডিলিট হয়ে যাবে।")) return; try { const uid = savedUser?.id || user?.id; if (uid) { await sb.from("videos").delete().eq("user_id", uid); await sb.from("profiles").delete().eq("id", uid); } await sb.auth.signOut(); } catch {} try { window.localStorage.clear(); } catch {} toast.success("অ্যাকাউন্ট ডিলিট হয়ে গেছে"); window.location.href = "/feed"; };
  return { currentUser: user || savedUser, showLogin, setShowLogin, loginWithGoogle, logout, deleteAccount };
}
