  const [fullVideo, setFullVideo] = useState<FeedItem | null>(null); const [followSet, setFollowSet] = useState<Set<string>>(() => new Set(getLocal("shorttok_follow", [])));
  const [openSound, setOpenSound] = useState<string | null>(null); const [showCreateWithSound, setShowCreateWithSound] = useState<string | null>(null);
  const [statuses, setStatuses] = useState<any[]>(() => getLocal("shorttok_status_list", [])); const [showAddStatus, setShowAddStatus] = useState(false); const [viewStatusIdx, setViewStatusIdx] = useState<number | null>(null);
  const [showStatusPage, setShowStatusPage] = useState(false); const [showAllCreators, setShowAllCreators] = useState(false); const [showPrivacy, setShowPrivacy] = useState(false); const [showExplorer, setShowExplorer] = useState(false);
  const [showCreate, setShowCreate] = useState(false); const [showNotif, setShowNotif] = useState(false); const [extraVideos, setExtraVideos] = useState<FeedItem[]>(() => getLocal("shorttok_feed_extra", []));
